solution_code:
#include <iostream>
#include <string>

class Label {
private:
    std::string m_text;

public:
    Label() {
        m_text = "untitled";
    }

    Label(const std::string& text) {
        m_text = text;
    }

    const std::string& getText() const { return m_text; }
};

int main() {
    int mode;
    std::cin >> mode;

    if (mode == 0) {
        Label lbl{};
        std::cout << lbl.getText() << '\n';
    } else {
        std::string text;
        std::cin >> text;
        Label lbl{ text };
        std::cout << lbl.getText() << '\n';
    }

    return 0;
}
